fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    if len == 0 {
        return (Vec::new(), Vec::new());
    }
    
    // Split at midpoint (rounded up for odd lengths)
    // This ensures for len > 1, both parts are non-empty and strictly shorter
    let mid = (len + 1) / 2;
    
    let mut first = Vec::new();
    let mut second = Vec::new();
    
    for i in 0..len {
        if i < mid {
            first.push(a[i]);
        } else {
            second.push(a[i]);
        }
    }
    
    (first, second)
}